  Context {HCEIL : HeapCeil}.

Definition pch_W (lo : Z) (sp : word) (P IN E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition pch_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' p' E' c' g',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (pch_W lo sp P IN E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells c' pad7 pad2)
    /\ rw_cells rsegs m' IN [C8 (wz p')]
    /\ rw_cells rsegs m' E (ErrCodeCells E')
    /\ rw_cells rsegs m' (P + 288) [C8 (wz 0)]
    /\ bytes_at rsegs m' p0 bs
    /\ pch_out c c' p0 (Z.of_nat (length bs)) p' E'
    /\ HttpCat m' g' /\ XStatics m'.

(* [comment removed for export] *)
Definition pch_pure (sp : word) (P IN E lo : Z) (c : pcore) (p0 : Z) (bs : list byte) : Prop :=
  pcore_ok c /\ pc_skip c < 2^62 /\ Z.of_nat (length bs) < 2^62
  /\ lo + 192 <= bv_unsigned sp /\ 0xb4000 <= lo /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0x90d70 <= p0) /\ p0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= P /\ P + 296 <= 2^64 /\ bv_unsigned sp <= IN /\ IN + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64
  /\ (P + 80 <= IN \/ IN + 8 <= P) /\ (P + 80 <= E \/ E + 24 <= P) /\ (IN + 8 <= E \/ E + 24 <= IN)
  /\ (P + 296 <= IN \/ IN + 8 <= P + 288) /\ (P + 296 <= E \/ E + 24 <= P + 288).

Definition pch_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (E0 : ecv) (g : bool),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells rsegs m IN [C8 (wz p0)] ->
  rw_cells rsegs m E (ErrCodeCells E0) ->
  rw_cells rsegs m (P + 288) [C8 (wz 0)] ->
  bytes_at rsegs m p0 bs ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) ->
  pch_pure sp P IN E lo c p0 bs ->
  mem_inv rsegs m ->
  evt rsegs (pch_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz (Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_CHUNK_HEADER) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition pch_ctx (m m1 : mem) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (P IN E lo : Z)
    (c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (pv : Z) (e1 e2 e3 : word) (g : bool)
    (j8 : list byte) (tmp : list cell) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -112) [CB 8 j8]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -104) [C8 (wz pv)]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -96) tmp
  /\ rw_cells rsegs m1 (bv_unsigned sp + -72) [C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells rsegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells rsegs m1 IN [C8 (wz p0)]
  /\ rw_cells rsegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ rw_cells rsegs m1 (P + 288) [C8 (wz 0)]
  /\ bytes_at rsegs m1 p0 bs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -112)
  /\ munch (pch_W lo sp P IN E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

(* [comment removed for export] *)
Definition pch_fcore (c c1 : pcore) (n : Z) : Prop :=
  pc_state c1 = pc_state c /\ pc_f c1 = pc_f c /\ pc_hlim c1 = pc_hlim c /\ pc_len c1 = pc_len c
  /\ pc_len0 c1 = pc_len0 c /\ pc_blim_has c1 = pc_blim_has c /\ 0 <= pc_blim c1 <= pc_blim c
  /\ 0 <= pc_skip c1 /\ (pc_skip c1 <= pc_skip c \/ pc_skip c1 < n)
  /\ 0 <= pc_skip c1 < 2^64 /\ 0 <= pc_f c1 < 2^14 /\ 0 <= pc_hlim c1 < 2^31.

Lemma pch_fail_exit : forall c c1 n e loc,
  pch_fcore c c1 n -> In e [HE_NEED_MORE; HE_BAD_CHUNK; HE_BAD_LINE_ENDING; HE_BAD_CHUNK_EXTENSION; HE_BODY_LIMIT] ->
  Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 ->
  pch_fail c c1 n (EC_http_loc e loc).
