(* [comment removed for export] *)
Local Ltac open_pch CTX PURE :=
  destruct CTX as (FR0 & PCL & TMP & FRhi & PC & IT & EC & CBH & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & SK62 & N62 & LO & IMG & QLO & QHI & PLO & PHI & ILO & IHI & ELO & EHI & DPI & DPE & DIE & DCI & DCE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold pch_W, G_HTTP_CAT in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold VP_PARSER in PC.

(* [comment removed for export] *)
Local Ltac pch_finish p' E' c' g' :=
  apply evt_done; unfold pch_post;
  do 16 eexists; exists p', E', c', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

