(* [comment removed for export] *)
Definition pch_exitN_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x
         s7v s6v s5v s4v s3v s2v s1v s0v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (pv p : Z) (e1 e2 e3 : word) (g : bool) (j8 junk : list byte),
  pch_ctx m m1 sp s7v s6v s5v s4v s3v s2v s1v s0v ra P IN E lo c1 pad7 pad2 p0 bs pv e1 e2 e3 g j8 [CB 24 junk] ->
  pch_pure sp P IN E lo c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
