(* [comment removed for export] *)
Definition pch_tcore (c c1 : pcore) : Prop :=
  pc_state c1 = pc_state c /\ pc_f c1 = pc_f c /\ pc_hlim c1 = pc_hlim c /\ pc_len0 c1 = pc_len0 c
  /\ pc_blim_has c1 = pc_blim_has c /\ 0 <= pc_blim c1 <= pc_blim c /\ 0 <= pc_f c1 < 2^14 /\ 0 <= pc_hlim c1 < 2^31.

Definition pch_tail_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3x s7x
         s7v s6v s5v s4v s3v s2v s1v s0v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (pv pe pp size eol : Z) (g : bool) (j8 : list byte) (tmp : list cell),
  pch_ctx m m1 sp s7v s6v s5v s4v s3v s2v s1v s0v ra P IN E lo c1 pad7 pad2 p0 bs pv (wz 0) (wz 0) (wz 0) g j8 tmp ->
  pch_pure sp P IN E lo c p0 bs -> pch_tcore c c1 ->
  p0 + 2 <= eol <= p0 + Z.of_nat (length bs) -> 0 <= size < 2^64 -> 0 <= pe < 2^64 -> 0 <= pp < 2^64 ->
  cells_size tmp = 24%nat ->
  evt rsegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz P) (wz pp) a1 a2 a3 a4 a5 a6 a7
              (wz pe) s3x (wz IN) (wz size) (wz eol) s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3a5c4) fc None m1 (seg_rom rsegs)).

